head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil25301";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil25301.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_goRegister_onclick
 * @description btn_goRegister 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_goRegister_onclick = async function(e){
    try {
        await scwin.goRegister()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25301.btn_goRegister_onclick' }); }
};

/**
 * @method
 * @name btn_goModify_onclick
 * @description btn_goModify 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_goModify_onclick = async function(e){
    try {
        await scwin.goModify()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25301.btn_goModify_onclick' }); }
};

/**
 * @method
 * @name btn_goSearch_onclick
 * @description btn_goSearch 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_goSearch_onclick = async function(e){
    try {
        await scwin.goSearch()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25301.btn_goSearch_onclick' }); }
};

/**
 * @method
 * @name btn_goManager_onclick
 * @description btn_goManager 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_goManager_onclick = function(e){
    try {
        scwin.goManager()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25301.btn_goManager_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initCallBack
 * @description init Call Back 처리
 * @param {*} result result
 * @returns {void}
 * @hidden N
 */
scwin.initCallBack = function (result) {
    return;
};

/**
 * @method
 * @name goRegister
 * @description go Register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goRegister = async function () {
    const goUrl = '/jldfil25302/jldfil25302.xml';
    const popwin = await $c.win.openPopup(goUrl, { id: "regCertWin", scrollbars: false, resizable: true, width: "500", height: "315", type: "pageFramePopup" }, { method: "registerCertificateForm", regMod: "REG" });
};

/**
 * @method
 * @name goModify
 * @description go Modify 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goModify = async function () {
    const goUrl = "/jldfil25302/jldfil25302.xml?method=registerCertificateForm&regMod=MOD";
    const popwin = await $c.win.openPopup(goUrl, { id: "regCertWin", scrollbars: false, resizable: false, width: "500", height: "315", type: "pageFramePopup" }, { method: "registerCertificateForm", regMod: "REG" });
};

/**
 * @method
 * @name goSearch
 * @description go Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goSearch = async function () {
    const goUrl = "/jldfil25302/jldfil25302.xml?method=searchCertificate";
    const popwin = await $c.win.openPopup(goUrl, { id: "certWin", scrollbars: false, resizable: false, width: "400", height: "285", type: "pageFramePopup" }, { method: "registerCertificateForm", regMod: "REG" });
};

/**
 * @method
 * @name goManager
 * @description go Manager 처리
 * @returns {void}
 * @hidden N
 */
scwin.goManager = function () {
    cwInit("initCallBack");
    INIWEBEX.openCertManager({ taskNm: "", isHtml5: false });
};

/**
 * @method
 * @name goAlert
 * @description go Alert 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goAlert = async function () {
    await $c.win.alert("시험가동 기간중에는 인증서 등록/재등록을 하실수 없습니다.");
};
